import org.deeptimeline.app.LabelSolver
import kotlin.math.abs
fun near(a:Double,b:Double,epsilon:Double=1e-7){check(abs(a-b)<=epsilon){"Expected $b, received $a"}}
fun main(){val gap=25.0;val free=doubleArrayOf(-200.0,-100.0,100.0,500.0);val natural=LabelSolver.solve(free,gap,0.0);for(i in free.indices)near(natural[i],free[i]);val clustered=doubleArrayOf(-10.0,0.0,1.0,2.0,3.0,4.0);val centered=LabelSolver.solve(clustered,gap,0.0);near(centered[1],0.0);near(centered[0],-25.0);for(i in 2 until centered.size)near(centered[i],(i-1)*gap);val middle=LabelSolver.solve(doubleArrayOf(-2.0,2.0),gap,0.0);near(middle[0],-12.5);near(middle[1],12.5);val tied=LabelSolver.solve(doubleArrayOf(0.0,0.0,0.0,100.0),gap,0.0);near(tied[0],-25.0);near(tied[1],0.0);near(tied[2],25.0);near(tied[3],100.0);val base=doubleArrayOf(-11.0,-3.0,2.0,3.0,5.0,60.0,90.0);var previous:DoubleArray?=null;for(step in -1000..1000){val shift=step*0.01;val shifted=DoubleArray(base.size){base[it]+shift};val result=LabelSolver.solve(shifted,gap,0.0);for(i in 1 until result.size)check(result[i]-result[i-1]>=gap-1e-7);previous?.let{old->for(i in result.indices)check(abs(result[i]-old[i])<0.4){"Discontinuous label $i at $shift: ${old[i]} -> ${result[i]}"}};previous=result};val atSwitchA=LabelSolver.solve(doubleArrayOf(-1.000001,0.999999),gap);val atSwitchB=LabelSolver.solve(doubleArrayOf(-0.999999,1.000001),gap);for(i in 0..1)check(abs(atSwitchA[i]-atSwitchB[i])<0.0001);for(zoom in listOf(1.0,2.0,10.0,24.0,25.0,100.0)){val geometry=doubleArrayOf(-1.0,0.0,1.0,2.0).map{it*zoom}.toDoubleArray();val solved=LabelSolver.solve(geometry,gap);near(solved[1],0.0);for(i in 1..3)check(solved[i]-solved[i-1]>=gap-1e-7)};val smoothAnchors=doubleArrayOf(-15.0,-1.0,0.0,1.0,40.0);val epsilon=0.00001;for(crossing in smoothAnchors){val left=LabelSolver.solve(smoothAnchors,gap,crossing-epsilon)[2];val at=LabelSolver.solve(smoothAnchors,gap,crossing)[2];val right=LabelSolver.solve(smoothAnchors,gap,crossing+epsilon)[2];check(abs((at-left)-(right-at))<0.0001){"Velocity discontinuity at $crossing"}};val enormous=LabelSolver.solve(DoubleArray(10000){0.0},gap);near(enormous[4999],-12.5);near(enormous[5000],12.5);for(i in 1 until enormous.size)near(enormous[i]-enormous[i-1],gap);println("Elastic label field: continuous scrolling, no focus threshold, anchored zero, crowding, ties, zoom release, 10k-event spacing: PASS")}
